// Command wordfreq reads all of standard input and prints the 10 most
// frequent ASCII words, one "<count> <word>" line each.
package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

const topN = 10

func main() {
	if err := run(os.Stdin, os.Stdout); err != nil {
		fmt.Fprintf(os.Stderr, "wordfreq: %v\n", err)
		os.Exit(1)
	}
}

func run(r io.Reader, w io.Writer) error {
	input, err := io.ReadAll(r)
	if err != nil {
		return fmt.Errorf("reading input: %w", err)
	}
	out := bufio.NewWriter(w)
	for _, wc := range topWords(countWords(input), topN) {
		fmt.Fprintf(out, "%d %s\n", wc.Count, wc.Word)
	}
	return out.Flush()
}

package main

import (
	"cmp"
	"slices"
)

// WordCount is a word together with its number of occurrences.
type WordCount struct {
	Word  string
	Count int
}

// lower maps ASCII letters to their lower-case form and every other byte to 0.
var lower = func() (t [256]byte) {
	for c := 'A'; c <= 'Z'; c++ {
		t[c] = byte(c) | 0x20
	}
	for c := 'a'; c <= 'z'; c++ {
		t[c] = byte(c)
	}
	return t
}()

// countWords returns the occurrences of every word in buf. A word is a
// maximal run of ASCII letters, folded to lower case. buf is lower-cased in
// place while scanning.
func countWords(buf []byte) []WordCount {
	index := make(map[string]int, 1<<12) // word -> position in counts
	var counts []WordCount
	n := len(buf)
	for i := 0; i < n; {
		if lower[buf[i]] == 0 {
			i++
			continue
		}
		start := i
		for ; i < n; i++ {
			c := lower[buf[i]]
			if c == 0 {
				break
			}
			buf[i] = c
		}
		word := buf[start:i]
		// Lookups keyed by string(word) do not allocate; only new words do.
		if k, ok := index[string(word)]; ok {
			counts[k].Count++
			continue
		}
		s := string(word)
		index[s] = len(counts)
		counts = append(counts, WordCount{Word: s, Count: 1})
	}
	return counts
}

// byCountThenWord orders by count descending, then by word ascending.
func byCountThenWord(a, b WordCount) int {
	if c := cmp.Compare(b.Count, a.Count); c != 0 {
		return c
	}
	return cmp.Compare(a.Word, b.Word)
}

// topWords returns at most limit entries of counts in byCountThenWord order.
func topWords(counts []WordCount, limit int) []WordCount {
	top := make([]WordCount, 0, limit+1)
	for _, wc := range counts {
		if len(top) == limit && byCountThenWord(wc, top[limit-1]) >= 0 {
			continue
		}
		pos, _ := slices.BinarySearchFunc(top, wc, byCountThenWord)
		top = slices.Insert(top, pos, wc)
		if len(top) > limit {
			top = top[:limit]
		}
	}
	return top
}

package main

import (
	"bytes"
	"strings"
	"testing"
)

func TestRun(t *testing.T) {
	tests := []struct {
		name, in, want string
	}{
		{"simple", "The cat and the hat.", "2 the\n1 and\n1 cat\n1 hat\n"},
		{"case folding", "Hello, hello! HELLO? world.\n", "3 hello\n1 world\n"},
		{"top ten and ties", "zeta eta theta iota kappa lambda mu nu xi omicron pi rho alpha beta alpha",
			"2 alpha\n1 beta\n1 eta\n1 iota\n1 kappa\n1 lambda\n1 mu\n1 nu\n1 omicron\n1 pi\n"},
		{"empty", "", ""},
		{"no words", "123 _' \xff\xc3(", ""},
		{"separators", "don't stop_me 4now, now-NOW", "3 now\n1 don\n1 me\n1 stop\n1 t\n"},
		{"non-ascii bytes", "caf\xc3\xa9 caf\xffe", "2 caf\n1 e\n"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var out bytes.Buffer
			if err := run(strings.NewReader(tt.in), &out); err != nil {
				t.Fatal(err)
			}
			if got := out.String(); got != tt.want {
				t.Errorf("got %q, want %q", got, tt.want)
			}
		})
	}
}
